class ZAYServer(ThreadingHTTPServer):
    allow_reuse_address=True
    daemon_threads=True

def main():
    srv=ZAYServer((HOST,PORT),H)
    local_url=f'http://127.0.0.1:{PORT}'
    print(f'ZAY COMPANY CLOUD 91 running on {HOST}:{PORT}')
    print('Health check: /health')
    print('Domain is optional: deploy first with a hosting URL, attach a custom domain later without changing the app.')
    if not IS_CLOUD:
        try: threading.Timer(1.0,lambda:webbrowser.open(local_url)).start()
        except Exception: pass
    try:
        srv.serve_forever(poll_interval=0.5)
    except KeyboardInterrupt:
        pass
    finally:
        srv.server_close()
if __name__=='__main__': main()
